sql.where:
${alias}.deleted_at IS NULL AND status = 0
AND c.category = #{postCategory}
AND p.title LIKE CONCAT('%', #{keyword}, '%')

mapper.select:
SELECT category_id
FROM post_category
WHERE category = #{category}

mapper.delete:
UPDATE post
SET deleted_at = NOW()
WHERE post_id = #{postId}
    AND member_id = #{memberId}
    AND status = #{temporaryStatus}
    AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM post
WHERE title = #{title}
    AND content = #{content}
    AND category_id = #{categoryId}
    AND member_id = #{memberId}
    AND status = 1
    AND deleted_at IS NULL
